// Some portions generated by Claude
/** The named-graph library's state rules, apart from React and the DOM (see use-workspace-library.tsx). */
import type { WorkspaceSnapshotMetadata } from "./workspace-snapshot-store.ts";

/**
 * The saved graph a binding (as Undo brings it back) names now: `known` holds what this page last saved or renamed
 * for each saved graph, and null for one it deleted. A binding this page never changed comes back as it was; a
 * revision another tab made since is still a conflict when the graph is saved.
 */
export function latestBinding(
  known: ReadonlyMap<string, WorkspaceSnapshotMetadata | null>,
  binding: WorkspaceSnapshotMetadata | null,
): WorkspaceSnapshotMetadata | null {
  if (!binding) return null;
  const latest = known.get(binding.id);
  return latest === undefined ? binding : latest;
}

/**
 * Shows or closes the native dialog as the page's dialog state says. The browser may close a modal dialog on its own
 * (a second Escape cannot be prevented), so this runs on every state change, not only when the dialog's kind changes.
 */
export function syncDialogElement(
  element: Pick<HTMLDialogElement, "open" | "showModal" | "close">,
  wanted: boolean,
): "opened" | "closed" | null {
  if (wanted && !element.open) {
    element.showModal();
    return "opened";
  }
  if (!wanted && element.open) {
    element.close();
    return "closed";
  }
  return null;
}
